var a=`0606-bissara`;var n=`world-0606`;var t=`MA`;var s=`northern-africa`;var r=4;var o=560;var l={en:`Bissara`,ua:`Біссара`};var d={en:`Bissara is a Morocco classic prepared with fava beans, garlic, lemon juice, parsley. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Біссара, страва кухні країни Марокко зі складниками: боби фава, часник, лимонний сік, петрушка. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Soak the dried beans or peas in plentiful cold water for 480 minutes, then drain and discard the soaking liquid; keep refrigerated in hot conditions.`,ua:`Замочіть сухі бобові у великій кількості холодної води на 480 хвилин, після чого злийте й вилийте воду від замочування; за спеки тримайте в холодильнику.`,t:[`soaking-legumes`],m:480,i:[[`fava-beans`,330,`g`],[`water`,800,`ml`]]},{en:`Drain soaked fava beans, cover with fresh water and simmer until they fall apart; blend into a smooth, pourable puree.`,ua:`Злийте воду із замочених бобів, залийте свіжою й варіть до розварювання; збийте на гладке пюре, яке можна наливати.`,t:[`boiling`],m:70,i:[[`water`,1050,`ml`],[`garlic`,4,`clove`],[`extra-virgin-olive-oil`,35,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`ground-cumin`,6,`g`],[`lemon-juice`,35,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`sweet-paprika`,4,`g`],[`parsley`,15,`g`],[`extra-virgin-olive-oil`,20,`ml`]]}];var m={slug:a,id:n,country:`MA`,region:s,servings:4,minutes:560,title:l,text:d,steps:g};export{t as country,m as default,n as id,o as minutes,s as region,r as servings,a as slug,g as steps,d as text,l as title};